import { NextRequest, NextResponse } from "next/server";

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { text, languageCode, speaker } = body as {
      text?: string;
      languageCode?: string;
      speaker?: string;
    };

    if (!text || text.trim().length === 0) {
      return NextResponse.json({ error: "Text is required" }, { status: 400 });
    }

    const apiKey = process.env.SARVAM_API_KEY;
    if (!apiKey) throw new Error("SARVAM_API_KEY is not configured");

    // CHANGED: Upgraded to bulbul:v3 and removed unsupported parameters
    const response = await fetch("https://api.sarvam.ai/text-to-speech", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "api-subscription-key": apiKey,
      },
      body: JSON.stringify({
        inputs: [text.slice(0, 500)], 
        target_language_code: languageCode || "en-IN",
        speaker: speaker || "shubh", // 'shubh' is standard for v3
        pace: 1.4, 
        speech_sample_rate: 24000, // v3 prefers 24000Hz
        model: "bulbul:v3", 
      }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Sarvam TTS error (${response.status}): ${errorText}`);
    }

    const data = await response.json();

    if (!data.audios || data.audios.length === 0) {
      throw new Error("No audio returned from TTS");
    }

    const audioBase64 = data.audios[0] as string;
    const audioBuffer = Buffer.from(audioBase64, "base64");

    return new NextResponse(audioBuffer, {
      headers: {
        "Content-Type": "audio/wav",
        "Content-Length": String(audioBuffer.length),
      },
    });
  } catch (error) {
    console.error("TTS error:", error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "TTS failed" },
      { status: 500 }
    );
  }
}